import request from "@/router/axios";
import qs from 'qs';
var hussarRequest = {
  get: function get(url, data) {
    data = data || {};
    return request({
      url: url,
      params: data,
      method: 'get'
    });
  },
  post: function post(url, data) {
    data = data || {};
    return request({
      url: url,
      data: data,
      method: 'post'
    });
  },
  postForm: function postForm(url, data) {
    return request({
      url: url,
      data: qs.stringify(data),
      method: 'post',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded'
      }
    });
  }
};
export default hussarRequest;
